def evaluate(sim, cfg):
    results = {}
    req = cfg.get("evaluation_metrics") or cfg.get("parameters", {}).get("evaluation_metrics", [])
    series = sim.aggregator.results()
    overall = series.get("overall_adoption_rate_over_time", [])
    if "adoption_rate_over_time" in req:
        results["adoption_rate_over_time"] = overall
    if "peak_adoption_rate" in req:
        results["peak_adoption_rate"] = max(overall) if overall else 0.0
    if "time_to_reach_threshold" in req:
        thr = cfg.get("parameters", {}).get("threshold_target", 0.7)
        t = next((i for i, v in enumerate(overall) if v >= thr), None)
        results["time_to_reach_threshold"] = t
    if "sustained_adoption_rate_last_14_days" in req:
        window = overall[-14:] if len(overall) >= 14 else overall
        results["sustained_adoption_rate_last_14_days"] = (sum(window)/len(window)) if window else 0.0
    if "policy_effect_size" in req:
        p = cfg.get("parameters", {})
        t0 = int(p.get("mandate_start_day", p.get("policy_mandate_start_day", 0)))
        t1 = int(p.get("mandate_end_day", p.get("policy_mandate_end_day", len(overall))))
        pre = overall[max(0, t0-7):t0]
        post = overall[t1:min(len(overall), t1+7)]
        results["policy_effect_size"] = (sum(post)/len(post) - sum(pre)/len(pre)) if pre and post else 0.0
    if "adoption_inequality_index" in req:
        # Simple variance across communities as proxy; extend to income groups once tracked
        by_comm = series.get("adoption_rate_by_community_over_time", [])
        if by_comm:
            last = by_comm[-1]
            vals = list(last.values())
            mu = sum(vals)/len(vals) if vals else 0.0
            var = sum((v-mu)**2 for v in vals)/len(vals) if vals else 0.0
            results["adoption_inequality_index"] = var
        else:
            results["adoption_inequality_index"] = 0.0
    if "stockout_days" in req:
        results["stockout_days"] = series.get("stockout_days", 0)
    if "average_price_paid" in req:
        results["average_price_paid"] = series.get("average_price_paid", 0.0)
    if "enforcement_events_count" in req:
        results["enforcement_events_count"] = series.get("enforcement_events_count", 0)
    return results

